"""Regenerate docs/REPORT_FACTS.md from experiments/**/metrics.json (the single source of numbers for every document)."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
E = ROOT / "experiments"


def L(n):
    return json.loads((E / n / "metrics.json").read_text(encoding="utf-8"))


def ms(m, k, nd=1):
    return f"{m[k]['mean']:.{nd}f} ± {m[k]['std']:.{nd}f}"


def ctrl_table(d):
    rows = ["| Controller | Avg delay (s) | Avg queue (veh) | Max queue | Throughput | Emergency delay (s) | Fuel idling (L) |", "|---|---|---|---|---|---|---|"]
    for c, r in d["results"].items():
        if c.startswith("_"):
            continue
        m = r["metrics"]
        rows.append(f"| {r['label']} | {ms(m, 'Avg delay / vehicle (s)')} | {ms(m, 'Avg queue (veh)')} | {m['Max approach queue']['mean']:.0f} | "
                    f"{m['Throughput (veh)']['mean']:.0f} | {ms(m, 'Emergency delay (s)')} | {m['Fuel wasted idling (L)']['mean']:.1f} |")
    return "\n".join(rows)


def main():
    c2, c3, sw, em, ab = L("controllers_2x2"), L("controllers_3x3"), L("demand_sweep"), L("emergency"), L("ablation")
    pr, vs, vy, vr, th, api = L("predictor"), L("vision_synthetic"), L("vision_yolo"), L("vision_real"), L("throughput"), L("api_latency")
    o = []
    w = o.append
    w("# REPORT FACTS - FlowSense (CSE-A-A10)\n")
    w("Single source of truth for every submission document. All numbers below are regenerated by `scripts/make_report_facts.py` from "
      "`experiments/**/metrics.json` (written by `scripts/run_experiments.py`, `scripts/eval_real_vision.py`, `scripts/measure_api.py`).\n")
    w("## 1. Project\n")
    w("- Title: AI-Based Smart Traffic Management; product **FlowSense**; batch CSE-A-A10 (Batch 10), TKR College of Engineering & Technology (Autonomous).")
    w("- Students: Buneti Harshitha 23K91A0548; Bhuvaneshwari Kadike 23K91A0537; Ambati Sai Nikhil Reddy 23K91A0510; Chapala Rohith Reddy 23K91A0551. Guide: Laxmi Prasanna.")
    w("- Base paper: M. Lamrabet, M. Alami Chentoufi, R. Ellaia, \"Emergency-Aware Adaptive Traffic Signal Control Using YOLO-Based Light-Bar Detection and SUMO System-Level Validation,\" IEEE Access, vol. 14, 2026, doi 10.1109/ACCESS.2026.3710015 (pp. 104922-104933).")
    w("- Companion reference paper: C. R. Goenawan, \"ASTM: Autonomous Smart Traffic Management System Using Artificial Intelligence CNN and LSTM,\" arXiv:2410.10929, 2024. Archived second candidate base paper: K. Gupta et al., NeCDM (GNN crowd-delivery traffic), IEEE TETCI vol. 10 no. 3, 2026, arXiv:2608.22555.")
    w("- Machine: Intel Core i5-12500 (6 cores / 12 threads), 15.7 GB RAM, Intel UHD 770 (no CUDA GPU - everything CPU), Windows 11 Pro, Python 3.11.9, torch 2.14.1+cpu, ultralytics 8.4.186, scikit-learn 1.5.0, numpy 1.26.4, OpenCV 4.11.0, FastAPI 0.143.3, pandas 2.2.1, Node 24.19, React 19, Vite 8.\n")
    w("## 2. What the product is (read from the code)\n")
    w("- `smart_traffic/sim.py` (415 lines): pure-Python 1 s-tick traffic-network simulator. Grid of 2x2 or 3x3 junctions, 4 approaches (N,E,S,W), two-phase signal (phase 0 NS, phase 1 EW), saturation discharge 0.5 veh/s/lane, start-up lost time 2 s, clearance (yellow + all-red) 3 s, link time 12 s between junctions, approach capacity 30 vehicles (spill-back), Poisson arrivals at entry roads (base rates N,S 0.15, E,W 0.10 veh/s) multiplied by demand slider x time-of-day profile (morning peak 08:30, evening peak 17:30). Vehicle mix car 68 %, bike 13 %, bus 6 %, truck 13 %; PCU weights car 1, bike 0.5, bus 3, truck 2, ambulance 1. 5 % of cars are red-light runners; wrong-way driver probability 0.0003 per entry-second.")
    w("- Four controllers on identical random demand: `fixed` (30 s split), `adaptive` (queue-actuated, min green 15, max 60, switch if other pressure > 2x current + 4), `emergency` (adaptive + pre-emption at ONE junction using ground-truth light-bar range, 5 s look-ahead; stands in for the base paper), `advanced` (this project: PCU-weighted pressure + 0.7 x ML forecast excess + inbound platoon within 8 s + fairness (head wait / 12) + spill-back damping x0.3 when downstream queue >= CAP-4; emergency look-ahead 15 s = green wave; min green 13).")
    w("- `smart_traffic/predictor.py` (59 lines): GradientBoostingRegressor (160 trees, depth 4, lr 0.08, subsample 0.9) forecasting each approach's queue 30 s ahead from 11 features (queue, PCU queue, queue lag 10 s and 30 s, 30 s inflow, inbound 15 s, is_green, green time, is_entry, sin/cos time of day); random 75/25 split; Random Forest and persistence baselines. Trained on 6 simulated runs (alternating 2x2/3x3, demand 0.7-1.6, 1800 s, snapshots every 10 s).")
    w("- `smart_traffic/vision.py` (201 lines): YOLOv8n (COCO weights, not fine-tuned) filtered to car/motorcycle/bus/truck; HSV red+blue light-bar cluster detector (red H 0-8/172-180, blue H 100-130, S>=120, V>=190, dilated intersection) used to relabel a vehicle box as `ambulance`; contour-based classical detector for the synthetic overhead scenes; density_report: PCU / capacity 14 -> LOW <0.35, MEDIUM <0.7, HIGH <1.0, JAMMED; recommended green 12 s if emergency else clamp(12+3.2 x PCU, 15, 60).")
    w("- Violations (red-light jumping, wrong-way driving) are generated by the simulator from ground-truth events and logged with a plate string and a randomly drawn confidence 0.86-0.99 - there is NO trained violation detector and no tracker. Emergency vehicles are known to the simulated controllers by ground truth; the vision module is not wired into the simulator's control loop.")
    w("- `backend/` (FastAPI, ~700 lines in 4 modules): HS256 token auth (stdlib), demo operator account (operator@flowsense.app / Flow@1234), predictor trains in a background thread on start (~6 s), 20 endpoints (below). No database: state is in-memory (one shared live simulation, benchmark cache, last-benchmark violations). `frontend/` React 19 + Vite 8 + Tailwind 4 + Recharts, 8 pages (Landing, Login, Live, Benchmark, Vision, Prediction, Violations, About). Legacy Streamlit app `app.py` (546 lines) remains.")
    w("- Ports: backend 8310, frontend 5310. Launch: `run.bat`.\n")
    w("### API endpoints\n")
    w("| Method | Path | Auth | Purpose |\n|---|---|---|---|")
    for r in [("GET", "/api/health", "no", "liveness, predictor_ready, yolo_available"), ("POST", "/api/auth/login", "no", "demo login -> token"), ("GET", "/api/auth/demo", "no", "demo credentials for the sign-in page"),
              ("GET", "/api/public/pulse", "no", "landing-page preview simulation"), ("GET", "/api/auth/me", "yes", "current user"), ("GET", "/api/meta", "yes", "controllers, grids, vehicle types"),
              ("GET", "/api/live", "yes", "live snapshot"), ("PUT", "/api/live/config", "yes", "grid, controller, demand, emergencies, ML toggle"), ("POST", "/api/live/step", "yes", "advance 1-900 s"),
              ("POST", "/api/live/ambulance", "yes", "inject an ambulance"), ("POST", "/api/live/reset", "yes", "restart simulation"), ("POST", "/api/benchmark", "yes", "4 controllers x seeds"),
              ("POST", "/api/benchmark/sweep", "yes", "delay vs demand"), ("GET", "/api/vision/synthetic", "yes", "synthetic scene + classical detector"), ("GET", "/api/vision/sample", "yes", "YOLOv8n on bundled photo"),
              ("POST", "/api/vision/analyze", "yes", "YOLOv8n on uploaded image (<=12 MB)"), ("GET", "/api/prediction", "yes", "model metrics, scatter, importance"), ("GET", "/api/prediction/live", "yes", "per-approach 30 s forecast"),
              ("POST", "/api/prediction/simulate", "yes", "advance 180 s"), ("GET", "/api/violations", "yes", "violation log and statistics")]:
        w("| " + " | ".join(r) + " |")
    w("\n## 3. Datasets (all synthetic or public; nothing private)\n")
    w("- **Simulator-generated data** (no external dataset for control): demand is stochastic (Poisson), seeded; SEEDS 40-44 for benchmarks. The predictor's training set is 6 simulated 1800 s runs under the `adaptive` controller (alternating 2x2 / 3x3; demand 0.7/1.0/1.3/1.6; start hours 7/8/12/17) -> **%d samples x %d features**, target = queue 30 s ahead (mean %.2f, std %.2f, max %.0f)." % (pr["n_samples"], pr["n_features"], pr["target_mean"], pr["target_std"], pr["target_max"]))
    w("- **Real traffic frames**: visaitech/vehicle-mixed-traffic-detection (Hugging Face, CC BY 4.0): 293 dashcam frames (640x480), 1,506 boxes, classes pedestrian / 2-wheeler / 3-wheeler / 4-wheeler, South Asian mixed traffic, split by source video (239 train / 54 val - all 293 used here because no model is trained on them).")
    w("- **Real ambulance photos**: shravya11/ambulance-images (Hugging Face, CC BY 4.0): 2,121 ambulance and 2,628 non-ambulance photos; the first 300 files (by name) of each folder were used (600 images).")
    w("- Bundled Ultralytics sample photo `bus.jpg` (1080x810) for the Vision page demo.")
    w("- Base-paper data (not used): 3,130 annotated light-bar images from three Roboflow Universe sets, 2,599/266/265 split; SUMO model of the Souissi roundabout, Rabat.\n")
    w("## 4. Controller benchmark (simulator, 5 seeds, demand x1.2, 1800 s, start 08:00, mean ± sample std over seeds)\n")
    w("### 2x2 junctions\n")
    w(ctrl_table(c2))
    d = c2["results"]["_derived"]
    w("\nDerived: advanced vs fixed delay **-%.1f %%**; vs adaptive **-%.1f %%** (within one standard deviation of adaptive); vs the base-paper style `emergency` controller **-%.1f %%**; the base-paper style controller is **%.1f %% worse than plain adaptive** on mean delay; emergency delay advanced vs fixed **-%.1f %%**, vs base-paper style **-%.1f %%**; idling fuel saved vs fixed %.1f L per 30-min run (idle fuel 0.6 L/h per queued vehicle, CO2 2.31 kg/L - assumptions in the simulator). Emergency vehicles spawned over 5 runs: %d per controller; pre-emptions: emergency %d, advanced %d." % (
        d["delay_cut_advanced_vs_fixed_pct"], d["delay_cut_advanced_vs_adaptive_pct"], d["delay_cut_advanced_vs_basepaper_pct"], -d["delay_cut_basepaper_vs_adaptive_pct"],
        d["emergency_cut_advanced_vs_fixed_pct"], d["emergency_cut_advanced_vs_basepaper_pct"], d["fuel_saved_L_advanced_vs_fixed_per_run"],
        c2["results"]["fixed"]["emergency_spawned"], c2["results"]["emergency"]["preemptions"], c2["results"]["advanced"]["preemptions"]))
    w("\nPer-seed average delay (s): " + "; ".join(f"{c}: " + ", ".join(f"{x:.1f}" for x in r["metrics"]["Avg delay / vehicle (s)"]["per_seed"]) for c, r in c2["results"].items() if not c.startswith("_")))
    w("\nThe first three seeds reproduce the Benchmark-page screenshot (fixed 73.0, adaptive 48.5, emergency-aware 51.2, advanced 45.4 s; emergency delay 18.7 / - / - / 5.1 s) because the API uses seeds 40+i.\n")
    w("### 3x3 junctions\n")
    w(ctrl_table(c3))
    d = c3["results"]["_derived"]
    w("\nDerived: advanced vs fixed **-%.1f %%**; vs adaptive **-%.1f %%**; vs base-paper style **-%.1f %%**; emergency delay vs fixed **-%.1f %%**, vs base-paper style **-%.1f %%**; base-paper style is %.1f %% worse than adaptive; red-light violations per run: base-paper style %.1f vs advanced %.1f (fixed %.1f, adaptive %.1f); fuel saved vs fixed %.1f L per run.\n" % (
        d["delay_cut_advanced_vs_fixed_pct"], d["delay_cut_advanced_vs_adaptive_pct"], d["delay_cut_advanced_vs_basepaper_pct"], d["emergency_cut_advanced_vs_fixed_pct"],
        d["emergency_cut_advanced_vs_basepaper_pct"], -d["delay_cut_basepaper_vs_adaptive_pct"],
        c3["results"]["emergency"]["metrics"]["Red-light violations"]["mean"], c3["results"]["advanced"]["metrics"]["Red-light violations"]["mean"], c3["results"]["fixed"]["metrics"]["Red-light violations"]["mean"], c3["results"]["adaptive"]["metrics"]["Red-light violations"]["mean"], d["fuel_saved_L_advanced_vs_fixed_per_run"]))
    w("## 5. Demand sweep (2x2, 3 seeds, 1200 s): average delay per vehicle (s)\n")
    w("| Demand | " + " | ".join(sw["series"]) + " |\n|---|" + "---|" * len(sw["series"]))
    for i, lv in enumerate(sw["levels"]):
        w(f"| x{lv} | " + " | ".join(f"{sw['series'][c][i]['delay_mean']:.1f}" for c in sw["series"]) + " |")
    w("\nAt the lowest demand (x0.6) `advanced` is **worse** than plain adaptive (26.4 s vs 20.6 s) - the extra pressure terms hold green for predicted/inbound traffic that is light; the advantage appears from x1.2 upward.\n")
    w("## 6. Emergency-heavy test (2x2, 3600 s, one ambulance per ~60 s, 5 seeds)\n")
    w("| Controller | n ambulances | mean delay (s) | median | p90 | max | network avg delay (s) |\n|---|---|---|---|---|---|---|")
    for c, r in em["results"].items():
        w(f"| {r['label']} | {r['n']} | {r['mean']:.1f} | {r['median']:.0f} | {r['p90']:.0f} | {r['max']:.0f} | {r['network_delay']:.1f} |")
    w("\nAmbulance delay is cut ~75 % by either pre-emption controller, but pre-emption costs the other traffic (network delay 50.1 s adaptive vs 57.7 s base-paper style vs 50.9 s advanced under this emergency load); the advanced controller's green wave and queue-aware logic recovers most of that cost.\n")
    w("## 7. Ablation of the advanced controller (2x2, 5 seeds, x1.2, 1800 s)\n")
    w("| Variant | Avg delay (s) | Avg queue | Emergency delay (s) |\n|---|---|---|---|")
    for k, m in ab["results"].items():
        w(f"| {k} | {ms(m, 'Avg delay / vehicle (s)')} | {m['Avg queue (veh)']['mean']:.1f} | {m['Emergency delay (s)']['mean']:.1f} |")
    w("\nReading: removing the ML forecast costs ~3 s of mean delay (47.4 vs 44.2 s; comparable to one standard deviation); the platoon look-ahead and the emergency green wave have small effects here (the green wave mostly changes emergency delay 5.7 -> 9.0 s); removing emergency pre-emption entirely gives the *lowest* network delay (42.4 s) but ambulance delay rises to 27.3 s - the safety/efficiency trade-off.\n")
    w("## 8. Queue forecaster (30 s horizon, %d samples, 11 features)\n" % pr["n_samples"])
    w("| Model | Random 75/25 split MAE (mean ± std, 5 splits) | R2 | Leave-one-simulation-out MAE | R2 |\n|---|---|---|---|---|")
    for m in pr["random_split_5x"]:
        a, b = pr["random_split_5x"][m], pr["leave_one_simulation_out"][m]
        w(f"| {m} | {a['mae_mean']:.3f} ± {a['mae_std']:.3f} | {a['r2_mean']:.3f} | {b['mae_mean']:.2f} ± {b['mae_std']:.2f} | {b['r2_mean']:.2f} |")
    s = pr["shipped_fit"]["metrics"]
    w("\nShipped model as the app trains it (one split, random_state=1): persistence MAE %.3f R2 %.3f; Random Forest MAE %.3f R2 %.3f; Gradient Boosting (used) **MAE %.3f R2 %.3f** (-%.0f %% MAE vs persistence). Fit time %.1f s. Feature importance (GB): " % (
        s["Persistence baseline"]["mae"], s["Persistence baseline"]["r2"], s["Random Forest"]["mae"], s["Random Forest"]["r2"], s["Gradient Boosting (used)"]["mae"], s["Gradient Boosting (used)"]["r2"],
        100 * (1 - s["Gradient Boosting (used)"]["mae"] / s["Persistence baseline"]["mae"]), pr["shipped_fit"]["fit_seconds"]) + ", ".join(f"{k} {v:.3f}" for k, v in sorted(pr["shipped_fit"]["importance"].items(), key=lambda x: -x[1])[:5]))
    g = pr["leave_one_simulation_out"]["Gradient Boosting (used)"]["mae_per_fold"]
    p = pr["leave_one_simulation_out"]["Persistence"]["mae_per_fold"]
    w("\nLeave-one-simulation-out MAE per held-out run (GB vs persistence): " + "; ".join(f"run{i + 1}: {a:.2f} vs {b:.2f}" for i, (a, b) in enumerate(zip(g, p))) +
      ". GB beats persistence in 5 of 6 held-out runs; the failure is run 4 (3x3, demand x1.6, 17:00 start - the only heavily congested run), where queues exceed the range seen in training and the tree model cannot extrapolate (and `predict` clips to 40). The random split overstates generalisation because snapshots from the same run are near-duplicates.\n")
    w("## 9. Vision\n")
    c = vs["results"]["clean"]
    w("### 9a. Synthetic overhead scenes (classical detector; 300 scenes, 2,754 objects; in-domain - the same author wrote the renderer and the detector)\n")
    w("| Condition | Recall | Precision | Class acc. (matched) | Ambulance recall | Ambulance false alarms |\n|---|---|---|---|---|---|")
    for k, v in vs["results"].items():
        w(f"| {k} | {v['recall']:.3f} | {v['precision']:.3f} | {v['class_accuracy_of_matched']:.3f} | {v['ambulance_recall']:.3f} | {v['ambulance_false_alarm_rate']:.3f} |")
    w("\nClean: exact vehicle count in %.0f %% of scenes, count MAE %.2f. The classical detector is brittle: Gaussian noise sigma 10 already produces zero detections; brightness x0.6 loses every light bar; 7x7 blur halves light-bar recall. YOLOv8n finds nothing in the synthetic scene (domain gap).\n" % (100 * c["count_exact_share"], c["count_mae"]))
    m = vr["mixed_traffic"]
    w("### 9b. YOLOv8n on real mixed-traffic dashcam frames (%d frames, %d vehicle boxes, conf 0.3, IoU 0.5, no tuning)\n" % (m["images"], m["gt_boxes_excluding_pedestrians"]))
    w("| GT class | GT boxes | TP | FP | FN | Precision | Recall | F1 |\n|---|---|---|---|---|---|---|---|")
    for k, v in m["per_class"].items():
        w(f"| {k} | {v['n_gt']} | {v['tp']} | {v['fp']} | {v['fn']} | {v['precision']:.3f} | {v['recall']:.3f} | {v['f1']:.3f} |")
    w("\nPredicted classes are mapped (bike->2-wheeler; car/bus/truck->4-wheeler); COCO has no auto-rickshaw class so 3-wheelers are never matched. Per-image count MAE %.2f; CPU latency %.1f ms mean (%.1f median) per 640x480 frame. Small/occluded motorcycles in dense dashcam traffic are mostly missed (recall 8 %%).\n" % (m["count_mae_per_image"], m["latency_ms_mean"], m["latency_ms_median"]))
    a = vr["ambulance_classification"]
    w("### 9c. Emergency-vehicle (light-bar) rule on real photos (300 ambulance + 300 non-ambulance images)\n")
    w("| Rule | TP | FP | FN | TN | Precision | Recall | F1 | False-alarm rate |\n|---|---|---|---|---|---|---|---|---|")
    for k, lab in (("lightbar_cluster_any", "any red+blue light-bar cluster in frame"), ("ambulance_flag_yolo_plus_lightbar", "YOLOv8n box with light bar on it (app's `ambulance` class)")):
        v = a[k]
        w(f"| {lab} | {v['tp']} | {v['fp']} | {v['fn']} | {v['tn']} | {v['precision']:.3f} | {v['recall']:.3f} | {v['f1']:.3f} | {v['false_alarm_rate']:.3f} |")
    w("\nThe rule almost never fires on real ambulance photos (recall 1.3 %% / 0.7 %%) while rarely false-alarming (0.3 %% / 0 %%): most photos show lights off, daylight, or sub-threshold colours. The synthetic result (recall 100 %%) does NOT transfer. YOLOv8n found at least one vehicle in %.1f %% of the real ambulance photos. The base paper's trained YOLO26m light-bar detector (P 0.73, R 0.69, mAP50 0.73 on 3,130 images) is the benchmark this project did not reach for emergency detection.\n" % (100 * a["yolo_found_any_vehicle_in_ambulance_images"]))
    y = vy["sample_photo"]
    w("### 9d. YOLOv8n on the bundled sample photo\n")
    w("Detections: " + ", ".join(f"{d['cls']} {d['conf']}" for d in y["detections"]) + f"; 0 light-bar clusters; latency {y['latency_ms_mean']:.1f} ms mean / {y['latency_ms_median']:.1f} median / {y['latency_ms_p95']:.1f} p95 (CPU, 20 runs after warm-up).\n")
    w("## 10. Performance\n")
    w("Simulator speed (wall time for 1800 simulated seconds): " + "; ".join(f"{k} {v['wall_s']:.2f} s ({v['speedup']:.0f}x real time)" for k, v in th.items() if isinstance(v, dict)) + f". Predictor inference 16 rows: {th['predictor_batch16_ms']:.2f} ms.\n")
    w("API latency on 127.0.0.1 (n=20 unless stated; mean / p95 ms): ")
    for r in api["results"]:
        w(f"- {r['endpoint']}: {r['mean_ms']:.1f}" + (f" / {r['p95_ms']:.1f}" if "p95_ms" in r else ""))
    w("\nThe first `vision sample` call includes loading yolov8n.pt (p95 is that one call). The first benchmark (4 controllers x 3 seeds x 1800 s) takes ~4.8 s; repeats are served from cache.\n")
    w("## 11. Testing\n")
    w("- `tests/` pytest suite: **38 tests, 38 passed** (24 engine/predictor/vision tests in `test_engine.py`, 14 API tests in `test_api.py` through FastAPI TestClient; run time ~28 s). Covers determinism, like-for-like demand across controllers, phase/cycle rules, spill-back bound, violation logging, emergency service, predictor vs persistence and output clipping, light-bar rule, density thresholds, auth token tamper/expiry, validation errors, benchmark range checks.")
    w("- `scripts/smoke_test.py`: **33 checks passed, 0 failed** against the running API (auth, live control, ambulance banner, grid switch, violations, prediction, benchmark, sweep, synthetic and YOLOv8 vision, bad upload).")
    w("- Not tested: concurrent users, browser automation beyond screenshot capture, load/stress, security penetration, any real camera or signal hardware.\n")
    w("## 12. Screenshot inventory (`docs/screenshots`, 1440x900, captured from the running app with live simulation data)\n")
    names = ["landing page, dark (live preview map)", "landing features, dark", "landing page, light theme", "sign-in page with demo account", "Live control centre (map, KPIs)", "Live control: road map + junction status table", "Benchmark: settings and KPI tiles", "Benchmark: delay and queue charts", "Benchmark: demand sweep", "Vision: synthetic scene detections", "Vision: density report", "Vision: YOLOv8n on sample photo", "Prediction: model metrics", "Prediction: live forecast", "Violations: statistics", "Violations: log", "About & paper", "About: pipeline", "Live control, light theme"]
    for i, n in enumerate(names, 1):
        f = sorted((ROOT / "docs" / "screenshots").glob(f"{i:02d}_*.png"))
        w(f"- {f[0].name if f else '??'}: {n}")
    w("\n## 13. Honest gaps (state plainly in every document)\n")
    for g_ in ["No SUMO/CARLA: validation uses an in-house simulator whose assumptions (demand, saturation flow, link time) are the author's; results are not comparable in absolute terms with the base paper's SUMO roundabout (ambulance travel 56 s, total waiting 19,887 s).",
               "Emergency vehicles are identified by ground truth inside the simulator; the vision light-bar detector is a separate demo module and is not closed-loop with the controllers.",
               "No light-bar/emergency-vehicle detector was trained; the HSV rule fails on real ambulance photos (recall 1.3 %). The base paper's YOLO26m (3,130 images, mAP50 0.73) was not reproduced.",
               "Vehicle detection is stock YOLOv8n; on real South Asian dashcam traffic its recall is 24 % (all vehicle boxes), 8 % for 2-wheelers, 0 % for 3-wheelers, 59 % for 4-wheelers at conf 0.3. It was not fine-tuned.",
               "Violation detection (red-light, wrong-way) is simulated from ground-truth events with random confidence values; there is no trained detector, no tracking, no ANPR.",
               "Inter-junction communication is simulated look-ahead on the transit queue (platoon within 8 s, emergency 15 s), not a network protocol.",
               "The queue forecaster generalises poorly to congestion levels outside its training runs (leave-one-simulation-out R2 ~0.04 mean); its closed-loop value is ~3 s of mean delay in the ablation.",
               "The `advanced` controller is only ~4-5 % better than plain queue-actuated control (within one std) and is worse than adaptive at very low demand; most of the headline -35 % vs fixed-time comes from adaptivity itself.",
               "No database, no persistence, one shared live simulation (single demo operator). Auth is a demo account.",
               "No real-camera video pipeline, no hardware-in-the-loop, no deployment trial."]:
        w("- " + g_)
    (ROOT / "docs" / "REPORT_FACTS.md").write_text("\n".join(o) + "\n", encoding="utf-8")
    print("wrote docs/REPORT_FACTS.md", len("\n".join(o)), "chars")


if __name__ == "__main__":
    main()
